create extension if not exists pgcrypto;
create type product_status as enum ('active','disabled','archived');
create type opportunity_status as enum ('pending','approved','rejected','posted','expired');
create table products (id uuid primary key default gen_random_uuid(),name text not null,url text not null,description text not null default '',one_liner text not null,categories text[] not null default '{}',audiences text[] not null default '{}',keywords text[] not null default '{}',status product_status not null default 'active',preferred_cta text not null default '',notes text not null default '',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table opportunities (id uuid primary key default gen_random_uuid(),reddit_post_id text not null unique,subreddit text not null,post_title text not null,post_body text not null default '',post_url text not null,author text not null,created_utc timestamptz not null,discovered_at timestamptz not null default now(),score integer not null check(score between 0 and 100),reasoning text not null,promotion_allowed boolean not null,matched_product_id uuid references products(id),match_score integer not null check(match_score between 0 and 100),proposed_reply text not null,edited_reply text,status opportunity_status not null default 'pending',source text not null,metadata jsonb not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table discovery_runs (id uuid primary key default gen_random_uuid(),started_at timestamptz not null default now(),completed_at timestamptz,status text not null check(status in ('running','completed','failed')),candidates_found integer not null default 0,opportunities_created integer not null default 0,error text,metadata jsonb not null default '{}');
alter table products enable row level security;alter table opportunities enable row level security;alter table discovery_runs enable row level security;
create policy "authenticated product access" on products for all to authenticated using (true) with check (true);
create policy "authenticated opportunity access" on opportunities for all to authenticated using (true) with check (true);
create policy "authenticated run access" on discovery_runs for select to authenticated using (true);
create or replace function set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end $$;
create trigger products_updated before update on products for each row execute function set_updated_at();create trigger opportunities_updated before update on opportunities for each row execute function set_updated_at();
